(()=>{const run=()=>{const grid=document.getElementById('sessions-grid');if(grid&&grid.children.length&&!document.getElementById('kirsty-session-26aug')){const card=document.createElement('div');card.className='card session-card';card.id='kirsty-session-26aug';card.innerHTML='<span class="pill">26 Aug 2026 · COMPLETED</span><h3>Progress review, Compass and attention</h3><p><b>Session:</b> Had a really good session with Kirsty. We talked through Darren\'s Compass and how it keeps the diary, therapy work and progress together as it continues to grow. Kirsty was impressed with what we have built and how clearly it shows the progress being made.</p><p><b>What we talked about:</b> Reviewed the week and the progress so far. We also touched on the possibility that some of my attention/concentration patterns could fit with ADHD or being on the spectrum. Kirsty cannot diagnose this, so this is not being recorded as a diagnosis, but she can keep those patterns in mind in how we work together.</p><p><b>Homework:</b> Kirsty gave me some Happiness flash cards. I will share the cards later so the exact wording and task can be added properly rather than guessed.</p><p><b>Next session:</b> Monday 14 September 2026 at 13:00.</p>';grid.prepend(card);}const recent=document.getElementById('recent-wins');if(recent&&!document.getElementById('progress-kirsty-26aug')){const x=document.createElement('div');x.id='progress-kirsty-26aug';x.className='item';x.innerHTML='<span class="dot"></span><div><div>Kirsty was impressed with Darren\'s Compass and how it shows the progress being made over time.</div><small>The app is becoming a useful living record of diary, therapy work and progress.</small></div>';recent.prepend(x);}const next=document.getElementById('next-appointment');if(next)next.textContent='14 Sep 2026';const nt=document.getElementById('next-appointment-time');if(nt)nt.textContent='13:00';const updated=document.getElementById('updated');if(updated)updated.textContent='Updated 26 August 2026';};let n=0;const t=setInterval(()=>{run();if(++n>16)clearInterval(t)},250);})();